import * as T from 'three';
function softBox(size,center){const radius=Math.min(size.x,size.y,size.z)*.15,g=new T.BoxGeometry(size.x,size.y,size.z,5,3,5),p=g.attributes.position,half=size.clone().multiplyScalar(.5).addScalar(-radius),v=new T.Vector3(),q=new T.Vector3();for(let i=0;i<p.count;i++){v.fromBufferAttribute(p,i);q.copy(v).clamp(half.clone().negate(),half);v.sub(q).normalize().multiplyScalar(radius).add(q).add(center);p.setXYZ(i,...v.toArray());}g.computeVertexNormals();return g;}
export function finishCab180(board){board.traverse(o=>{if(!o.isMesh||o.userData.finish180)return;if(/Placa[_ ]mando149/.test(o.name)){o.geometry.computeBoundingBox();const b=o.geometry.boundingBox;const size=b.getSize(new T.Vector3()),center=b.getCenter(new T.Vector3());center.y+=(size.y-.045)/2;size.y=.045;o.geometry=softBox(size,center);o.material=o.material.clone();o.material.color.set('#33464c');o.material.roughness=.6;o.material.metalness=.35;}o.userData.finish180=true;});}
export function crisp180(map){map.anisotropy=16;map.generateMipmaps=true;map.minFilter=T.LinearMipmapLinearFilter;map.magFilter=T.LinearFilter;map.colorSpace=T.SRGBColorSpace;return map;}

export function labelControls190(board,doc){const names={open:'ABRIR PUERTAS',close:'CERRAR PUERTAS',voice:'AVISO DE VOZ',align:'AJUSTAR PARADA',cab:'CAMBIAR CABINA',emergency:'EMERGENCIA'};const groups=[];board.traverse(o=>{if(names[o.userData.control149])groups.push(o);});for(const g of groups){if(g.userData.label190)continue;g.userData.label190=true;g.traverse(o=>{if(/^Rotulacion149_/.test(o.name))o.visible=false;});const c=doc.createElement('canvas');c.width=768;c.height=144;const x=c.getContext?.('2d');if(!x?.fillText)continue;const danger=g.userData.control149==='emergency';x.fillStyle=danger?'#4e2525':'#182b33';x.fillRect(0,0,768,144);x.fillStyle=danger?'#ffb9a8':'#dce8e7';x.fillRect(0,0,7,144);x.font='600 58px Arial';x.textAlign='center';x.textBaseline='middle';x.fillText(names[g.userData.control149],384,75);const map=crisp180(new T.CanvasTexture(c)),plate=new T.Mesh(new T.PlaneGeometry(.205,.038),new T.MeshBasicMaterial({map,toneMapped:false}));plate.name='Etiqueta legible190';plate.position.set(0,.013,.087);plate.rotation.x=-Math.PI/2;plate.raycast=()=>{};g.add(plate);}}
